    details.open = this.open.has(key);
    const summary = node("summary", "lpt-side-summary");
    const icon = node("img", "lpt-side-icon");
    icon.src = UI_ICONS[{ apps: "apps", tracking: "track", source: "helper", appearance: "look", advanced: "advanced" }[key] ?? "advanced"];
    icon.alt = "";
    icon.setAttribute("aria-hidden", "true");
    icon.draggable = false;
